export const getRouteComponent = (path: string): React.LazyExoticComponent<React.ComponentType<Record<string, never>>> | null => {
  return routeComponents[path] || null;
};

// src/context/AuthContext.tsx

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { authService, User as AuthUser } from '../services/authService';

// Role-to-dashboard route mapping
export const ROLE_DASHBOARD_MAP: Record<string, string> = {
  patient: '/patient/dashboard',
  client: '/patient/dashboard',
  doctor: '/doctor/dashboard',
  hospital: '/hospital/dashboard',
  pharmacy: '/pharmacy/dashboard',
  admin: '/admin/dashboard',
  super_admin: '/admin/dashboard',
};

interface AuthContextType {
  user: AuthUser | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  login: (credentials: Parameters<typeof authService.login>[0]) => Promise<void>;
  register: (data: Parameters<typeof authService.register>[0]) => Promise<void>;
  logout: () => Promise<void>;
  hasRole: (roles: string | string[]) => boolean;
}

const AuthContext = createContext<AuthContextType>({
  user: null,
  isAuthenticated: false,
  isLoading: true,
  login: async () => {},
  register: async () => {},
  logout: async () => {},
  hasRole: () => false,
});

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const currentUser = authService.getCurrentUser();
    if (currentUser && authService.isAuthenticated()) {
      setUser(currentUser);
    }
    setIsLoading(false);
  }, []);

  const login = useCallback(async (credentials: Parameters<typeof authService.login>[0]) => {
    const response = await authService.login(credentials);
    setUser(response.user);
  }, []);

  const register = useCallback(async (data: Parameters<typeof authService.register>[0]) => {
    const response = await authService.register(data);
    setUser(response.user);
  }, []);

  const logout = useCallback(async () => {
    await authService.logout();
    setUser(null);
  }, []);

  const hasRole = useCallback(
    (roles: string | string[]): boolean => {
      if (!user) return false;
      const roleList = Array.isArray(roles) ? roles : [roles];
      return roleList.includes(user.role);
    },
    [user],
  );

  return (
    <AuthContext.Provider
      value={{
        user,
        isAuthenticated: !!user,
        isLoading,
        login,
        register,
        logout,
        hasRole,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuthContext = () => useContext(AuthContext);

// src/context/ThemeContext.tsx
import React, { createContext, useContext, useState, useEffect } from 'react';

interface ThemeContextType {
  isDarkMode: boolean;
  toggleDarkMode: () => void;
}

const ThemeContext = createContext<ThemeContextType>({
  isDarkMode: false,
  toggleDarkMode: () => {}
});

export const ThemeProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const saved = localStorage.getItem('darkMode');
    return saved === 'true';
  });

  useEffect(() => {
    localStorage.setItem('darkMode', isDarkMode.toString());
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const toggleDarkMode = () => setIsDarkMode(!isDarkMode);

  return (
    <ThemeContext.Provider value={{ isDarkMode, toggleDarkMode }}>
      {children}
    </ThemeContext.Provider>
  );
};

export const useTheme = () => useContext(ThemeContext);

// src/App.tsx
import React from 'react';
import { BrowserRouter } from 'react-router-dom';
import { Provider } from 'react-redux';
import { PersistGate } from 'redux-persist/integration/react';
import { Toaster } from 'react-hot-toast';
import { store, persistor } from './store';
import { AppRoutes } from './app/routes/AppRoutes';

// ==========================
// PAGE LOADER
// ==========================
const PageLoader = () => (
  <div className="flex items-center justify-center min-h-screen bg-[#030508]">
    <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-cyan-500" />
  </div>
);

// ==========================
// ROOT APP
// ==========================
function App() {
  return (
    <Provider store={store}>
      <PersistGate loading={<PageLoader />} persistor={persistor}>
        <BrowserRouter>
          <Toaster
            position="top-right"
            toastOptions={{
              style: {
                background: '#1e293b',
                color: '#fff',
                border: '1px solid rgba(255,255,255,0.1)',
              },
            }}
          />
          <AppRoutes />
        </BrowserRouter>
      </PersistGate>
    </Provider>
  );
}

export default App;

// src/app/routes/AppRoutes.tsx
import React, { Suspense } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { useSelector } from 'react-redux';
import { routeConfig, type RouteItem } from './routeConfig';
import type { RootState } from '../../store';

// ============================================
// PAGE LOADER
// ============================================
const PageLoader: React.FC = () => (
  <div className="flex items-center justify-center min-h-screen bg-[#030508]">
    <div className="flex flex-col items-center gap-4">
      <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-cyan-500" />
      <p className="text-white/30 text-sm">Loading...</p>
    </div>
  </div>
);

// ============================================
// AUTH GUARD
// ============================================
const AuthGuard: React.FC<{ route: RouteItem; children: React.ReactNode }> = ({ route, children }) => {
  const auth = useSelector((state: RootState) => state.auth);
  const sessionToken = sessionStorage.getItem('auth_token');
  const userRole = sessionStorage.getItem('user_role');

  const isAuthenticated = auth?.isAuthenticated && sessionToken;

  // Not logged in
  if (!isAuthenticated) {
    return <Navigate to="/login" replace />;
  }

  // Wrong role
  if (route.roles && !route.roles.includes(userRole || '')) {
    return <Navigate to="/" replace />;
  }

  return <>{children}</>;
};

// ============================================
// PUBLIC GUARD
// ============================================
const PublicGuard: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const auth = useSelector((state: RootState) => state.auth);
  const sessionToken = sessionStorage.getItem('auth_token');
  const userRole = sessionStorage.getItem('user_role');

  if (auth?.isAuthenticated && sessionToken && userRole) {
    return <Navigate to={`/${userRole}/dashboard`} replace />;
  }

  return <>{children}</>;
};

// ============================================
// HOSPITAL DETAILS WRAPPER
// ============================================
import HospitalDetails from '../../components/hospital/EmergencyServices';

const HospitalDetailsWrapper: React.FC = () => (
  <HospitalDetails
    icuBeds={{ total: 50, available: 15, occupied: 35, covid: 10, nonCovid: 25, emergency: 5, cardiac: 8, pediatric: 5, neonatal: 2 }}
    resources={[]}
    staff={[]}
  />
);

// ============================================
// MAIN ROUTES
// ============================================
export const AppRoutes: React.FC = () => {
  return (
    <Suspense fallback={<PageLoader />}>
      <Routes>
        {routeConfig.map((route) => {
          const Component = route.component;

          // Special case for hospital/:id with props
          if (route.path === '/hospital/:id') {
            return (
              <Route
                key={route.path}
                path={route.path}
                element={<HospitalDetailsWrapper />}
              />
            );
          }

          // Protected routes
          if (route.isProtected) {
            return (
              <Route
                key={route.path}
                path={route.path}
                element={
                  <AuthGuard route={route}>
                    <Component />
                  </AuthGuard>
                }
              />
            );
          }

          // Login/Register - redirect if already logged in
          if (route.path === '/login' || route.path === '/register') {
            return (
              <Route
                key={route.path}
                path={route.path}
                element={
                  <PublicGuard>
                    <Component />
                  </PublicGuard>
                }
              />
            );
          }

          // Public routes
          return (
            <Route
              key={route.path}
              path={route.path}
              element={<Component />}
            />
          );
        })}
      </Routes>
    </Suspense>
  );
};

